import{_ as a,c as t,o as n,a5 as s}from"./chunks/framework.CUJoMJm2.js";const g=JSON.parse('{"title":"Sideband Relay Protocol (SBRP)","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbrp/index.md","filePath":"protocols/sbrp/index.md","lastUpdated":1768070912000}'),i={name:"protocols/sbrp/index.md"};function r(o,e,l,d,c,p){return n(),t("div",null,[...e[0]||(e[0]=[s(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/sbrp.md for this page in Markdown format</div><h1 id="sideband-relay-protocol-sbrp" tabindex="-1">Sideband Relay Protocol (SBRP) <a class="header-anchor" href="#sideband-relay-protocol-sbrp" aria-label="Permalink to “Sideband Relay Protocol (SBRP)”">​</a></h1><p><strong>Version:</strong> 0.1.0<br><strong>Status:</strong> Draft</p><blockquote><p><strong>Authority</strong>: Navigation (Non-normative)<br><strong>Purpose</strong>: Overview, intent, roles, and navigation to normative documents.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>SBRP enables secure communication between local daemons and browser-based UIs via a relay server. The protocol uses a hybrid trust model:</p><ul><li><strong>Relay is trusted</strong> for token validation, access enforcement, and routing</li><li><strong>Relay cannot decrypt</strong> application payloads (end-to-end encrypted)</li><li><strong>Relay cannot perform undetectable MITM</strong> on established TOFU pins</li></ul><p>This provides persistent multi-device access while ensuring message confidentiality.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────┐         ┌─────────┐         ┌─────────┐</span></span>
<span class="line"><span>│ Browser │◄──TLS──►│  Relay  │◄──TLS──►│ Daemon  │</span></span>
<span class="line"><span>│         │  auth   │ Server  │  auth   │         │</span></span>
<span class="line"><span>└─────────┘         └─────────┘         └─────────┘</span></span>
<span class="line"><span>     │                   │                   │</span></span>
<span class="line"><span>     │      [auth, routing, presence]        │</span></span>
<span class="line"><span>     │                   │                   │</span></span>
<span class="line"><span>     └────────── E2EE encrypted ─────────────┘</span></span>
<span class="line"><span>           [signed handshake, encrypted payloads]</span></span></code></pre></div><h3 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to “Design Goals”">​</a></h3><ul><li>Persistent access from any device</li><li>Multi-device support (mobile, desktop, multiple browsers)</li><li>End-to-end encryption for application data</li><li>Cryptographic MITM protection (not just trust-based)</li><li>Standard OAuth/session authentication</li><li>Zero local TLS/certificate configuration</li></ul><h3 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-Goals”">​</a></h3><ul><li>Protecting against compromised relay (auth/routing layer)</li><li>Transport-level anonymity</li><li>Hiding metadata (timing, message size, which daemon you&#39;re connecting to)</li></ul><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to “Terminology”">​</a></h2><p><strong>Client</strong>: Session initiator authenticated via control plane. Generates ephemeral X25519 keys per session. No persistent cryptographic identity. Verifies daemon via TOFU. May be a browser, CLI, native app, or any non-daemon participant.</p><p><strong>Daemon</strong>: Long-lived agent with Ed25519 identity keypair. Registers with control plane via API key; connects to relay using presence tokens. Reachable only through relay.</p><p><strong>Relay</strong>: Routing authority and token validator. Not an encryption endpoint. Does not authenticate directly; validates tokens issued by control plane.</p><h2 id="trust-model" tabindex="-1">Trust Model <a class="header-anchor" href="#trust-model" aria-label="Permalink to “Trust Model”">​</a></h2><p>SBRP uses a layered trust model where the relay handles authentication and routing while being cryptographically excluded from message content.</p><table tabindex="0"><thead><tr><th>What Relay Can Do</th><th>What Relay Cannot Do</th></tr></thead><tbody><tr><td>Validate tokens from control plane</td><td>Decrypt message content (E2EE)</td></tr><tr><td>Route connections between parties</td><td>Perform undetectable MITM after TOFU trust</td></tr><tr><td>See metadata (timing, size)</td><td>Forge daemon identity (Ed25519 signatures)</td></tr><tr><td>Drop or delay messages (DoS)</td><td>—</td></tr></tbody></table><p><strong>TOFU Identity Pinning</strong>: Clients persist daemon identity public keys locally. First connection trusts the control-plane-provided key; subsequent connections verify against the pinned key. Key changes abort the connection and require user approval.</p><p>See <a href="./threat-model">threat-model.md</a> for detailed threat analysis and attack resistance.</p><h2 id="protocol-flow" tabindex="-1">Protocol Flow <a class="header-anchor" href="#protocol-flow" aria-label="Permalink to “Protocol Flow”">​</a></h2><h3 id="daemon-registration-one-time" tabindex="-1">Daemon Registration (One-Time) <a class="header-anchor" href="#daemon-registration-one-time" aria-label="Permalink to “Daemon Registration (One-Time)”">​</a></h3><p>Daemon generates Ed25519 identity keypair on first run and registers with control plane.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Daemon                           Control Plane                    Relay</span></span>
<span class="line"><span>   │                                  │                              │</span></span>
<span class="line"><span>   │── POST /api/daemons/register ───►│                              │</span></span>
<span class="line"><span>   │   { apiKey, identityPublicKey }  │                              │</span></span>
<span class="line"><span>   │◄─── 200 { daemonId, presenceToken }                             │</span></span>
<span class="line"><span>   │                                  │                              │</span></span>
<span class="line"><span>   │── WSS /relay?token=&lt;jwt&gt; ────────┼─────────────────────────────►│</span></span></code></pre></div><h3 id="client-connection" tabindex="-1">Client Connection <a class="header-anchor" href="#client-connection" aria-label="Permalink to “Client Connection”">​</a></h3><p>Client lists available daemons, obtains session token, and connects.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Client                           Control Plane                    Relay</span></span>
<span class="line"><span>   │                                  │                              │</span></span>
<span class="line"><span>   │── GET /api/daemons ─────────────►│                              │</span></span>
<span class="line"><span>   │◄─── 200 [{ id, identityPublicKey, status }]                     │</span></span>
<span class="line"><span>   │                                  │                              │</span></span>
<span class="line"><span>   │── POST /api/sessions ───────────►│                              │</span></span>
<span class="line"><span>   │   { daemonId }                   │                              │</span></span>
<span class="line"><span>   │◄─── 200 { relayUrl, token }──────│                              │</span></span>
<span class="line"><span>   │                                  │                              │</span></span>
<span class="line"><span>   │── WSS /relay?token=&lt;jwt&gt; ────────┼─────────────────────────────►│</span></span></code></pre></div><h3 id="e2ee-handshake" tabindex="-1">E2EE Handshake <a class="header-anchor" href="#e2ee-handshake" aria-label="Permalink to “E2EE Handshake”">​</a></h3><p>After WebSocket connection, client and daemon perform authenticated key exchange.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Client                     Relay                    Daemon</span></span>
<span class="line"><span>   │                         │                         │</span></span>
<span class="line"><span>   │── HandshakeInit (0x01) ►│── forward ─────────────►│</span></span>
<span class="line"><span>   │   [32B X25519 key]      │                         │</span></span>
<span class="line"><span>   │                         │                         │  Generate ephemeral</span></span>
<span class="line"><span>   │                         │                         │  Sign with Ed25519</span></span>
<span class="line"><span>   │◄───────────────────────────── HandshakeAccept (0x02)</span></span>
<span class="line"><span>   │                         │   [32B key + 64B sig]   │</span></span>
<span class="line"><span>   │  Verify signature       │                         │</span></span>
<span class="line"><span>   │  Derive session keys    │                         │</span></span>
<span class="line"><span>   │◄══════════ Encrypted frames (0x03) ══════════════►│</span></span></code></pre></div><p>See <a href="./cryptography-and-wire">cryptography-and-wire.md</a> for signature construction, key derivation, and wire format details.</p><h2 id="end-to-end-flow" tabindex="-1">End-to-End Flow <a class="header-anchor" href="#end-to-end-flow" aria-label="Permalink to “End-to-End Flow”">​</a></h2><h3 id="happy-path-walkthrough" tabindex="-1">Happy Path Walkthrough <a class="header-anchor" href="#happy-path-walkthrough" aria-label="Permalink to “Happy Path Walkthrough”">​</a></h3><ol><li>Daemon registers with control plane, stores Ed25519 identity keypair</li><li>Client authenticates, obtains session token targeting daemon</li><li>Client connects to relay, sends HandshakeInit with ephemeral X25519 key</li><li>Daemon signs its ephemeral key with identity key, sends HandshakeAccept</li><li>Client verifies signature against pinned identity (TOFU)</li><li>Both derive session keys via HKDF with transcript hash</li><li>Encrypted messages flow through relay as opaque bytes</li></ol><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as Client</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant R as Relay</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant D as Daemon</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;R: Connect + Session Token</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;D: Forward HandshakeInit</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D-&gt;&gt;R: HandshakeAccept (signed ephemeral)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;C: Forward</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,D: E2EE Session Established</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;R: Data (encrypted)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;D: Forward (opaque bytes)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D-&gt;&gt;R: Data (encrypted)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;C: Forward (opaque bytes)</span></span></code></pre></div><h3 id="failure-path-session-interruption" tabindex="-1">Failure Path: Session Interruption <a class="header-anchor" href="#failure-path-session-interruption" aria-label="Permalink to “Failure Path: Session Interruption”">​</a></h3><ol><li>Daemon disconnects (network issue, process restart)</li><li>Relay sends <code>Control(session_paused)</code> to client</li><li>Client suspends sends, shows UI indicator</li><li>If daemon reconnects within grace period: <ul><li>Daemon sends <code>Signal(ready)</code> for sessions with retained state</li><li>Relay sends <code>Control(session_resumed)</code> to client</li></ul></li><li>If state is lost or grace expires: <ul><li>Relay sends <code>Control(session_expired)</code> to client</li><li>Client initiates full reconnect with new handshake</li></ul></li></ol><p>See <a href="./state-machine">state-machine.md</a> for complete state transition rules.</p><h2 id="message-categories" tabindex="-1">Message Categories <a class="header-anchor" href="#message-categories" aria-label="Permalink to “Message Categories”">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Frame Type</th><th>Direction</th><th>Purpose</th></tr></thead><tbody><tr><td>Endpoint</td><td>0x01–0x03</td><td>E2EE</td><td>Handshake and encrypted data</td></tr><tr><td>Signal</td><td>0x04</td><td>Daemon → Relay</td><td>Session lifecycle commands</td></tr><tr><td>Control</td><td>0x20</td><td>Relay → Endpoint</td><td>Notifications and errors</td></tr><tr><td>Keepalive</td><td>0x10–0x11</td><td>Either</td><td>Connection liveness detection</td></tr></tbody></table><p><strong>Endpoint frames</strong> participate in E2EE and are forwarded by relay without inspection. <strong>Signal frames</strong> are daemon-to-relay commands (ready, close). <strong>Control frames</strong> are relay-generated notifications (session_paused, rate_limited). <strong>Keepalive frames</strong> are connection-scoped and never forwarded.</p><p>See <a href="./cryptography-and-wire">cryptography-and-wire.md</a> for wire format details.</p><h2 id="relay-server-responsibilities" tabindex="-1">Relay Server Responsibilities <a class="header-anchor" href="#relay-server-responsibilities" aria-label="Permalink to “Relay Server Responsibilities”">​</a></h2><p>The relay operates as a frame router with these core responsibilities:</p><table tabindex="0"><thead><tr><th>Responsibility</th><th>Description</th></tr></thead><tbody><tr><td>Token validation</td><td>Validate JWTs from control plane; enforce claims</td></tr><tr><td>Routing</td><td>Route session-bound frames between paired connections</td></tr><tr><td>Presence tracking</td><td>Track daemon online/offline; notify clients of changes</td></tr><tr><td>Rate limiting</td><td>Enforce message rate and payload size limits</td></tr><tr><td>Keepalive handling</td><td>Respond to Ping with Pong; detect dead connections</td></tr></tbody></table><p>The relay MUST NOT interpret encrypted payloads or derive information from their content.</p><p>See <a href="./authentication">authentication.md</a> for token validation details.</p><h2 id="reconnection" tabindex="-1">Reconnection <a class="header-anchor" href="#reconnection" aria-label="Permalink to “Reconnection”">​</a></h2><h3 id="daemon-reconnection" tabindex="-1">Daemon Reconnection <a class="header-anchor" href="#daemon-reconnection" aria-label="Permalink to “Daemon Reconnection”">​</a></h3><p>Daemons may reconnect within a grace period and resume sessions if state is retained:</p><ul><li><strong>State retained</strong>: Daemon sends <code>Signal(ready)</code> → Client receives <code>session_resumed</code></li><li><strong>State lost</strong>: Daemon sends <code>Signal(close)</code> → Client receives <code>session_expired</code></li><li><strong>Non-resumable daemons</strong>: Relay auto-expires all sessions on reconnect</li></ul><h3 id="client-reconnection" tabindex="-1">Client Reconnection <a class="header-anchor" href="#client-reconnection" aria-label="Permalink to “Client Reconnection”">​</a></h3><p>Clients always perform a full reconnect:</p><ol><li>Obtain new session token from control plane</li><li>Connect to relay with fresh token</li><li>Full E2EE handshake (new ephemeral keys)</li></ol><p>See <a href="./state-machine">state-machine.md</a> for state transition details.</p><h2 id="multi-device-support" tabindex="-1">Multi-Device Support <a class="header-anchor" href="#multi-device-support" aria-label="Permalink to “Multi-Device Support”">​</a></h2><ul><li>Each client has an independent E2EE session with the daemon</li><li>Daemon maintains separate key state per client (keyed by SessionID)</li><li>Messages are not broadcast; each client gets its own responses</li><li>Identity pinning is per client/device storage (not synced)</li></ul><h2 id="security-properties" tabindex="-1">Security Properties <a class="header-anchor" href="#security-properties" aria-label="Permalink to “Security Properties”">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Mechanism</th></tr></thead><tbody><tr><td>Message confidentiality</td><td>ChaCha20-Poly1305 E2EE</td></tr><tr><td>Message integrity</td><td>Poly1305 authentication tag</td></tr><tr><td>Daemon authenticity</td><td>Ed25519 identity signatures</td></tr><tr><td>Forward secrecy</td><td>Ephemeral X25519 per session</td></tr><tr><td>Replay protection</td><td>Sequence numbers + sliding window</td></tr><tr><td>MITM detection</td><td>TOFU identity pinning</td></tr></tbody></table><p>See <a href="./threat-model">threat-model.md</a> for attack resistance analysis.</p><h2 id="delegation" tabindex="-1">Delegation <a class="header-anchor" href="#delegation" aria-label="Permalink to “Delegation”">​</a></h2><p><strong>This protocol delegates:</strong></p><ul><li><strong>Wire format</strong>: Defines own binary framing (does not use SBP frames directly)</li><li><strong>Error codes</strong>: Defines own Control code taxonomy</li><li><strong>Application protocol</strong>: Encrypted payloads contain SBP frames</li></ul><p><strong>This protocol defines:</strong></p><ul><li><strong>E2EE session</strong>: Handshake, key derivation, encrypted transport</li><li><strong>Control codes</strong>: Relay-to-endpoint notifications</li><li><strong>Signal codes</strong>: Daemon-to-relay lifecycle commands</li><li><strong>Authentication</strong>: Token-based relay access</li></ul><h2 id="document-authority" tabindex="-1">Document Authority <a class="header-anchor" href="#document-authority" aria-label="Permalink to “Document Authority”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Primary</th><th>Supporting</th></tr></thead><tbody><tr><td>Crypto + wire format</td><td><a href="./cryptography-and-wire">cryptography-and-wire.md</a></td><td>—</td></tr><tr><td>State transitions</td><td><a href="./state-machine">state-machine.md</a></td><td>—</td></tr><tr><td>Control code semantics</td><td><a href="./state-machine">state-machine.md</a></td><td><a href="./control-codes">control-codes.md</a></td></tr><tr><td>Control code values</td><td><a href="./control-codes">control-codes.md</a></td><td>—</td></tr><tr><td>Authentication</td><td><a href="./authentication">authentication.md</a></td><td>—</td></tr><tr><td>Threat model</td><td><a href="./threat-model">threat-model.md</a></td><td>—</td></tr><tr><td>Test specification</td><td><a href="./conformance">conformance.md</a></td><td>—</td></tr><tr><td>Security verification</td><td>cryptography-and-wire.md, state-machine.md</td><td><a href="./security-checklist">security-checklist.md</a></td></tr></tbody></table><h2 id="local-terminology" tabindex="-1">Local Terminology <a class="header-anchor" href="#local-terminology" aria-label="Permalink to “Local Terminology”">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th><th>See also</th></tr></thead><tbody><tr><td>Session Key</td><td>Derived HKDF key for this connection</td><td><a href="./../glossary#session-key">glossary</a></td></tr><tr><td>TOFU</td><td>Trust-on-first-use identity pinning</td><td><a href="./../glossary#tofu">glossary</a></td></tr><tr><td>Control Frame</td><td>Relay-generated notification (0x20)</td><td><a href="./../glossary#control-frame-sbrp">glossary</a></td></tr><tr><td>Signal Frame</td><td>Daemon-to-relay lifecycle command (0x04)</td><td>—</td></tr><tr><td>Endpoint Frame</td><td>Session-bound E2EE frame (0x01–0x03)</td><td>—</td></tr></tbody></table><h2 id="recommended-reading-order" tabindex="-1">Recommended Reading Order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to “Recommended Reading Order”">​</a></h2><ol><li><strong>index.md</strong> (this document) — overview and navigation</li><li><strong><a href="./cryptography-and-wire">cryptography-and-wire.md</a></strong> — crypto invariants + wire format</li><li><strong><a href="./state-machine">state-machine.md</a></strong> — lifecycle and control semantics</li><li><strong><a href="./control-codes">control-codes.md</a></strong> — code catalog</li><li><strong><a href="./authentication">authentication.md</a></strong> — token validation</li><li><strong><a href="./conformance">conformance.md</a></strong> — what must pass</li></ol><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to “Related Documents”">​</a></h2><ul><li><a href="./../architecture">Protocol Architecture</a>: Layer stack, wrapping rules</li><li><a href="./../glossary">Glossary</a>: Shared terminology</li><li>ADR-002: Naming matrix (SBRP abbreviation)</li></ul>`,75)])])}const m=a(i,[["render",r]]);export{g as __pageData,m as default};
